<?php
// Automatic first answer for the website chat. Built only from prices.json (generated by tools/build_pages.py
// from the same SERVICES data as the order form), so the bot never invents a price. Keiko still replies personally.
if (!defined('KA_CHAT')) { http_response_code(404); exit; }

function bot_money(float $v): string { return '$' . (floor($v) == $v ? number_format($v, 0) : number_format($v, 2)); }

function bot_reply(string $msg, bool $first): string {
  $P = json_decode((string)@file_get_contents(__DIR__ . '/prices.json'), true);
  $q = strtolower($msg);
  $words = ['one' => 1, 'two' => 2, 'three' => 3, 'four' => 4, 'five' => 5, 'six' => 6, 'seven' => 7, 'eight' => 8, 'nine' => 9, 'ten' => 10];
  $q = preg_replace_callback('/\b(one|two|three|four|five|six|seven|eight|nine|ten)\b/', function ($m) use ($words) { return (string)$words[$m[1]]; }, $q);
  $out = [];
  if ($first) $out[] = "Thanks for your message! Keiko will reply here and by email, usually within 6 hours (WIB). For a faster reply, message Keiko on Discord: discord.gg/FbgWxMPjf";
  if (!is_array($P)) return implode("\n\n", $out);

  // "are you open?", "how long?", "how do I order / pay?" (facts from the site, never invented)
  $info = [];
  if (preg_match('/\b(open|slots?|available|availability|taking|accept(ing)?)\b|buka|komisi/', $q)) {
    $openNow = !isset($P['_status']['open']) || $P['_status']['open'];
    $sl = $P['_status']['slots'] ?? []; $slTxt = isset($sl['VTuber']) ? ' VTuber model slots left: ' . (int)$sl['VTuber'] . '.' : '';
    $info[] = $openNow ? 'Yes, commissions are open right now and Keiko can start soon.' . $slTxt : 'Commissions are closed at the moment. Join the Discord server to hear when they open: discord.gg/FbgWxMPjf';
  }
  if (preg_match('/how long|turnaround|deadline|when.*(done|ready|finish)|lama|berapa minggu/', $q)) $info[] = 'Every commission is done within 3 weeks at most, with updates at every stage. Rush delivery (+25%) takes about half the time.';
  if (preg_match('/how (do|can) i (order|commission|pay|start)|payment|paypal|pay with|cara (order|bayar)/', $q)) $info[] = 'To order: pick your options in the order form (keikoartist.com/?order=VTuber), or add several services to the cart. You get an invoice right away and pay with PayPal (card or PayPal balance): in full, 50% now, or in 3 payments for orders above $150. Full refund before work starts.';
  if (preg_match('/revision|revisi/', $q)) $info[] = 'Revisions: unlimited at the sketch stage, and 2 minor revisions after coloring.';
  if ($info) $out[] = implode("\n", $info);
  $priceAsk = preg_match('/price|how much|cost|rate|quote|budget|\$|harga|berapa|total/', $q);
  $vt = $P['VTuber'] ?? null;
  $size = preg_match('/full\s*-?\s*body|fullbody/', $q) ? 'Full body' : (preg_match('/half\s*-?\s*body|halfbody|half/', $q) ? 'Half body' : (preg_match('/bust/', $q) ? 'Bust' : ''));
  $type = preg_match('/rig\s*only|only\s*(the\s*)?rig|rigging only|just (the )?rig/', $q) ? 'Rig only'
        : (preg_match('/art\s*only|only\s*(the\s*)?art|no rig|without rig|psd only/', $q) ? 'Art only' : 'Art + Rig');

  if ($vt && $size !== '') {
    $pk = null; foreach ($vt['packages'] as $p) if ($p[0] === "$size · $type") $pk = $p;
    if ($pk) {
      $ad = []; foreach ($vt['addons'] as $a) $ad[$a[0]] = (float)$a[1];
      $lines = ["$size · $type: " . bot_money($pk[1])]; $sub = (float)$pk[1];
      $n = function ($re) use ($q) { return preg_match($re, $q, $m) ? max(1, min(20, (int)$m[1])) : 0; };
      if (isset($ad['VBridger']) && preg_match('/v\s*-?\s*bridger/', $q)) { $lines[] = 'VBridger: +' . bot_money($ad['VBridger']); $sub += $ad['VBridger']; }
      $h = $n('/(\d+)\s*(?:extra\s*)?hand\s*toggles?/'); if (!$h && preg_match('/hand\s*toggles?/', $q)) $h = 1;
      if ($h && isset($ad['Hand toggle'])) { $lines[] = "$h hand toggle" . ($h > 1 ? 's' : '') . ': +' . bot_money($ad['Hand toggle'] * $h); $sub += $ad['Hand toggle'] * $h; }
      $x = $n('/(\d+)\s*(?:extra\s*)?(?:expressions?|toggles?)(?!\s*hand)/');
      if ($x && !preg_match('/\d+\s*(?:extra\s*)?hand\s*toggles?/', $q) && isset($ad['Extra expression / toggle'])) { $lines[] = "$x extra expression" . ($x > 1 ? 's / toggles' : ' / toggle') . ': +' . bot_money($ad['Extra expression / toggle'] * $x); $sub += $ad['Extra expression / toggle'] * $x; }
      $o = $n('/(\d+)\s*(?:extra\s*)?outfits?/'); if ($o && isset($ad['Extra outfit'])) { $lines[] = "$o extra outfit" . ($o > 1 ? 's' : '') . ': +' . bot_money($ad['Extra outfit'] * $o); $sub += $ad['Extra outfit'] * $o; }
      $hs = $n('/(\d+)\s*(?:extra\s*)?hair\s*styles?/'); if ($hs && isset($ad['Extra hairstyle'])) { $lines[] = "$hs extra hairstyle" . ($hs > 1 ? 's' : '') . ': +' . bot_money($ad['Extra hairstyle'] * $hs); $sub += $ad['Extra hairstyle'] * $hs; }
      if (preg_match('/commercial|merch/', $q) && isset($ad['Commercial / merch rights'])) { $lines[] = 'Commercial / merch rights: +' . bot_money($ad['Commercial / merch rights']); $sub += $ad['Commercial / merch rights']; }
      $tax = round($sub * 0.13, 2);
      $t = "Estimate (USD):\n- " . implode("\n- ", $lines) . "\nSubtotal " . bot_money($sub) . " + 13% tax " . bot_money($tax) . " = " . bot_money($sub + $tax);
      if (preg_match('/advanced?|pro\s*rig/', $q) && $type !== 'Art only') $t .= "\nFull rigging (head turns, blinking, lip-sync, hair & clothing physics) is included in Art + Rig.";
      $t .= "\nAbout " . ($vt['eta'] ?: '2–3 weeks') . ". Keiko confirms the final price. You can send it now with the order form: keikoartist.com/?order=VTuber";
      $out[] = $t;
      return implode("\n\n", $out);
    }
  }
  // other services by name
  $map = ['pngtuber' => 'PNGTuber', 'emote' => 'Emotes', 'banner' => 'Banner', 'logo' => 'VTuber Logo', 'overlay' => 'Stream Overlay', 'background' => 'Background', 'pfp' => 'Custom PFP', 'profile pic' => 'Custom PFP', 'chibi' => 'Chibi VTuber', 'pet' => 'VTuber Pet', 'package' => 'VTuber Packages', 'debut' => 'VTuber Packages'];
  $found = [];
  foreach ($map as $k => $name) if (strpos($q, $k) !== false && isset($P[$name])) $found[$name] = $P[$name];
  if ($found) {
    $l = [];
    foreach ($found as $name => $s) {
      $pk = array_map(function ($p) use ($s) { return $p[0] . ' ' . bot_money($p[1]) . (!empty($s['qty']) ? ' each' : ''); }, array_slice($s['packages'], 0, 4));
      $l[] = "$name: " . implode(', ', $pk);
    }
    $out[] = "Prices (USD, + 13% tax):\n- " . implode("\n- ", $l) . "\nFull list: keikoartist.com/vtuber-pricing";
  } elseif ($priceAsk && $vt) {
    $g = function ($n) use ($vt) { foreach ($vt['packages'] as $p) if ($p[0] === $n) return bot_money($p[1]); return '?'; };
    $out[] = "Live2D VTuber prices (USD, + 13% tax): Art + Rig bust " . $g('Bust · Art + Rig') . ", half body " . $g('Half body · Art + Rig') . ", full body " . $g('Full body · Art + Rig') . ". Art only from " . $g('Bust · Art only') . ".\nFull list: keikoartist.com/vtuber-pricing";
  }
  // nothing specific matched: the first message still gets a useful overview (prices, slots, how to order)
  if ($first && count($out) === 1 && $vt) {
    $g = function ($n) use ($vt) { foreach ($vt['packages'] as $p) if ($p[0] === $n) return bot_money($p[1]); return '?'; };
    $sl = $P['_status']['slots']['VTuber'] ?? null; $open = !isset($P['_status']['open']) || $P['_status']['open'];
    $out[] = "While you wait, the basics:\n- Live2D VTuber model (art + rig): bust " . $g('Bust · Art + Rig') . ", half body " . $g('Half body · Art + Rig') . ", full body " . $g('Full body · Art + Rig') . " (+ 13% tax)"
      . "\n- PNGTuber, emotes, overlays, logos and more: keikoartist.com/vtuber-pricing"
      . "\n- " . ($open ? 'Commissions are open' . ($sl !== null ? ' (' . (int)$sl . ' VTuber slots left)' : '') . ', every commission done within 3 weeks' : 'Commissions are closed right now')
      . "\n- Order form: keikoartist.com/?order=VTuber";
  }
  // later messages before Keiko replies: a short "got it" when nothing matched (the chat API sends it at most once an hour)
  if (!$first && !$out) $out[] = "Got it! Keiko has your message and will reply here soon. For a faster reply, message Keiko on Discord: discord.gg/FbgWxMPjf";
  return implode("\n\n", $out);
}
